starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "origin_domain_name" {
  description = "Input variable origin_domain_name."
  type        = string
  default     = "example.com"
}

variable "certificate_arn" {
  description = "Input variable certificate_arn."
  type        = string
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_cloudfront_distribution" "this" {
  # TODO - Complete the aws_cloudfront_distribution resource.
  # Add the arguments and nested blocks required for aws_cloudfront_distribution.
}
